import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <>
<div className="bg-gray-100 text-white min-h-screen">
  <header className="flex justify-between items-center p-0">
    <nav className="flex items-center justify-between w-full bg-gray-800 p-4 rounded-md">
      {/* Logo on the extreme left */}
      <img src="logo.png" width="64" alt="Logo" className="ml-0" />

      {/* Add spacing between logo and h1 */}
      <h1 className="text-xl ml-4">Sanskriti Chauhan</h1> 

      {/* Navigation links on the right */}
      <div className="flex space-x-8 ml-auto">
        <Link to="/" className="hover:text-gray-400 text-white text-xl font-serif font-pacifico">Home</Link>
        <Link to="/about" className="hover:text-gray-400 text-white text-xl font-serif font-pacifico">About</Link>
        <Link to="/photography" className="hover:text-gray-400 text-white text-xl font-serif font-pacifico">Photography</Link>
        <Link to="/portfolio" className="hover:text-gray-400 text-white text-xl font-serif font-pacifico">Portfolio</Link>
      </div>
    </nav>
  </header>

    <div className="flex flex-row gap-32 mx-auto w-fit my-">

    </div>
</div>


    </>
  );
};

export default Home;
